62: impl<'a> DatFrame<'a> {
63:     /// Parses a single `.DAT` frame from a borrowed byte slice with zero allocations.
64:     ///
65:     /// Validates the `0x55` magic byte, checks the minimum frame length, verifies
66:     /// the frame checksum (attempting CRC16 first with primary `0x3692` and fallback `0xFFFF`,
67:     /// then CRC32 if length $\ge 13$), and extracts the raw payload slice.
68:     ///
69:     /// # Errors
70:     /// * Returns `FlightReaderError::UnexpectedEof` if `frame_bytes` is empty.
71:     /// * Returns `FlightReaderError::SyncNotFound` if `frame_bytes[0] != 0x55`.
72:     /// * Returns `FlightReaderError::InvalidFrameLength` if declared length $< 11$.
73:     /// * Returns `FlightReaderError::TruncatedRecord` if `frame_bytes.len() < length`.
74:     /// * Returns `FlightReaderError::ChecksumMismatch` if checksum verification fails.
75:     pub fn parse(frame_bytes: &'a [u8]) -> Result<DatFrame<'a>> {
76:         if frame_bytes.is_empty() {
77:             return Err(FlightReaderError::UnexpectedEof);
78:         }
79: 
80:         if frame_bytes[0] != DAT_MAGIC {
81:             return Err(FlightReaderError::SyncNotFound);
82:         }
83: 
84:         if frame_bytes.len() < 2 {
85:             return Err(FlightReaderError::UnexpectedEof);
86:         }
87: 
88:         let length = frame_bytes[1];
89:         if (length as usize) < 11 {
90:             return Err(FlightReaderError::InvalidFrameLength {
91:                 length,
92:                 minimum: 11,
93:             });
94:         }
95: 
96:         if frame_bytes.len() < length as usize {
97:             return Err(FlightReaderError::TruncatedRecord {
98:                 expected: length as usize,
99:                 available: frame_bytes.len(),
100:             });
101:         }
102: 
103:         let frame_slice = &frame_bytes[..length as usize];
104: 
105:         // Determine checksum type and verify
106:         let (checksum_type, checksum_len) = match checksum::verify_crc16(frame_slice) {
107:             Ok(()) => (DatChecksumType::Crc16, 2),
108:             Err(crc16_err) => {
109:                 if (length as usize) >= 13 {
110:                     match checksum::verify_crc32(frame_slice) {
111:                         Ok(()) => (DatChecksumType::Crc32, 4),
112:                         Err(_) => return Err(crc16_err),
113:                     }
114:                 } else {
115:                     return Err(crc16_err);
116:                 }
117:             }
118:         };
119: 
120:         let sequence = frame_slice[2];
121:         let payload_id = u16::from_le_bytes([frame_slice[3], frame_slice[4]]);
122:         let timestamp_ticks = u32::from_le_bytes([
123:             frame_slice[5],
124:             frame_slice[6],
125:             frame_slice[7],
126:             frame_slice[8],
127:         ]);
128:         let payload = &frame_slice[HEADER_LEN..length as usize - checksum_len];
129: 
130:         Ok(DatFrame {
131:             magic: DAT_MAGIC,
132:             length,
133:             sequence,
134:             payload_id,
135:             timestamp_ticks,
136:             payload,
137:             checksum_type,
138:         })
139:     }
