238: impl<'a> Iterator for DatFrameIterator<'a> {
239:     type Item = Result<DatFrame<'a>>;
240: 
241:     fn next(&mut self) -> Option<Self::Item> {
242:         while self.cursor < self.buffer.len() {
243:             // Find next occurrence of 0x55 magic byte
244:             let rel_sync = match self.buffer[self.cursor..]
245:                 .iter()
246:                 .position(|&b| b == DAT_MAGIC)
247:             {
248:                 Some(pos) => pos,
249:                 None => {
250:                     self.cursor = self.buffer.len();
251:                     return None;
252:                 }
253:             };
254: 
255:             let sync_pos = self.cursor + rel_sync;
256:             self.cursor = sync_pos;
257: 
258:             // Must have at least 2 bytes (magic + length) to evaluate candidate
259:             if self.cursor + 1 >= self.buffer.len() {
260:                 self.cursor = self.buffer.len();
261:                 return None;
262:             }
263: 
264:             let cand_len = self.buffer[self.cursor + 1] as usize;
265: 
266:             // Minimum allowable frame length for any checksum type is 11 bytes
267:             if cand_len < 11 {
268:                 self.cursor += 1;
269:                 continue;
270:             }
271: 
272:             // Check if full candidate frame is available in the buffer
273:             if self.cursor + cand_len > self.buffer.len() {
274:                 self.cursor += 1;
275:                 continue;
276:             }
277: 
278:             let cand_slice = &self.buffer[self.cursor..self.cursor + cand_len];
279: 
280:             match DatFrame::parse(cand_slice) {
281:                 Ok(frame) => {
282:                     self.cursor += cand_len;
283:                     return Some(Ok(frame));
284:                 }
285:                 Err(_) => {
286:                     // Checksum or format verification failed, advance 1 byte to seek next sync
287:                     self.cursor += 1;
288:                     continue;
289:                 }
290:             }
291:         }
292: 
293:         None
294:     }
295: }
