11: /// CRC16-CCITT generator polynomial ($x^{16} + x^{12} + x^5 + 1$).
12: pub const CRC16_POLYNOMIAL: u16 = 0x1021;
13: 
14: /// Primary initial seed used by DJI flight controllers for `.DAT` CRC16 checksums.
15: pub const CRC16_INIT_PRIMARY: u16 = 0x3692;
16: 
17: /// Secondary fallback initial seed used by certain legacy or alternate DJI firmware.
18: pub const CRC16_INIT_FALLBACK: u16 = 0xFFFF;
19: 
20: /// IEEE 802.3 32-bit generator polynomial (reversed / LSB-first).
21: pub const CRC32_POLYNOMIAL: u32 = 0xEDB8_8320;
