23: /// Compile-time precomputed lookup table for CRC16-CCITT (polynomial `0x1021`).
24: const CRC16_TABLE: [u16; 256] = {
25:     let mut table = [0u16; 256];
26:     let mut i = 0;
27:     while i < 256 {
28:         let mut crc = (i as u16) << 8;
29:         let mut j = 0;
30:         while j < 8 {
31:             if (crc & 0x8000) != 0 {
32:                 crc = (crc << 1) ^ CRC16_POLYNOMIAL;
33:             } else {
34:                 crc <<= 1;
35:             }
36:             j += 1;
37:         }
38:         table[i] = crc;
39:         i += 1;
40:     }
41:     table
42: };
