50:         let mut j = 0;
51:         while j < 8 {
52:             if (crc & 1) != 0 {
53:                 crc = (crc >> 1) ^ CRC32_POLYNOMIAL;
54:             } else {
55:                 crc >>= 1;
56:             }
57:             j += 1;
58:         }
59:         table[i] = crc;
