89: /// Verifies the 16-bit CRC16-CCITT checksum at the end of a `.DAT` frame slice.
90: ///
91: /// The checksum is verified by calculating the CRC16 over `&frame_bytes[0 .. frame_bytes.len() - 2]`
92: /// with the primary initial value `0x3692` (and optional fallback `0xFFFF`), then comparing
93: /// against the Little-Endian `u16` stored in the final 2 bytes.
94: ///
95: /// # Errors
96: /// * Returns `FlightReaderError::InvalidFrameLength` if `frame_bytes.len() < 11`.
97: /// * Returns `FlightReaderError::ChecksumMismatch` if neither the primary nor fallback CRC matches.
98: pub fn verify_crc16(frame_bytes: &[u8]) -> Result<()> {
99:     if frame_bytes.len() < 11 {
100:         return Err(FlightReaderError::InvalidFrameLength {
101:             length: frame_bytes.len() as u8,
102:             minimum: 11,
103:         });
104:     }
105: 
106:     let len = frame_bytes.len();
107:     let expected = u16::from_le_bytes([frame_bytes[len - 2], frame_bytes[len - 1]]);
108:     let data = &frame_bytes[..len - 2];
109: 
110:     let calc_primary = calc_crc16_ccitt(data, CRC16_INIT_PRIMARY);
111:     if calc_primary == expected {
112:         return Ok(());
113:     }
114: 
115:     let calc_fallback = calc_crc16_ccitt(data, CRC16_INIT_FALLBACK);
116:     if calc_fallback == expected {
117:         return Ok(());
118:     }
119: 
120:     Err(FlightReaderError::ChecksumMismatch {
121:         expected: expected as u32,
122:         calculated: calc_primary as u32,
123:     })
124: }
