175: /// Verifies the 32-bit IEEE 802.3 CRC32 checksum at the end of a `.DAT` frame slice.
176: ///
177: /// The checksum is verified by calculating the CRC32 over `&frame_bytes[0 .. frame_bytes.len() - 4]`,
178: /// then comparing against the Little-Endian `u32` stored in the final 4 bytes.
179: ///
180: /// # Errors
181: /// * Returns `FlightReaderError::InvalidFrameLength` if `frame_bytes.len() < 13`.
182: /// * Returns `FlightReaderError::ChecksumMismatch` if the calculated checksum differs from expected.
183: pub fn verify_crc32(frame_bytes: &[u8]) -> Result<()> {
184:     if frame_bytes.len() < 13 {
185:         return Err(FlightReaderError::InvalidFrameLength {
186:             length: frame_bytes.len() as u8,
187:             minimum: 13,
188:         });
189:     }
190: 
191:     let len = frame_bytes.len();
192:     let expected = u32::from_le_bytes([
193:         frame_bytes[len - 4],
194:         frame_bytes[len - 3],
195:         frame_bytes[len - 2],
196:         frame_bytes[len - 1],
197:     ]);
198:     let data = &frame_bytes[..len - 4];
199:     let calculated = calc_crc32(data);
200: 
201:     if calculated == expected {
202:         Ok(())
203:     } else {
204:         Err(FlightReaderError::ChecksumMismatch {
205:             expected,
206:             calculated,
207:         })
208:     }
209: }
