175: /// Classify a DJI `.txt` log version into its architectural and cryptographic capabilities.
176: ///
177: /// # Invariants
178: /// - Versions 1 through 6: 1-byte length width, no scrambling, details at EOF.
179: /// - Versions 7 through 11: 2-byte length width, cyclic XOR scrambling, details at EOF.
180: /// - Version 12: 2-byte length width, cyclic XOR scrambling, details relocated to header offset.
181: /// - Versions 13 through 14: 2-byte length width, AES encryption, details at header offset.
182: /// - All other versions: rejected with [`FlightReaderError::UnsupportedVersion`].
183: ///
184: /// # Errors
185: /// Returns [`FlightReaderError::UnsupportedVersion`] if `version` is not in `1..=14`.
186: pub fn classify_version(version: u8) -> Result<VersionCapabilities, FlightReaderError> {
187:     match version {
188:         1..=6 => Ok(VersionCapabilities {
189:             version,
190:             record_len_width: 1,
191:             scramble_type: ScrambleType::None,
192:             details_location: DetailsLocation::EndOfFile,
193:         }),
194:         7..=11 => Ok(VersionCapabilities {
195:             version,
196:             record_len_width: 2,
197:             scramble_type: ScrambleType::Xor,
198:             details_location: DetailsLocation::EndOfFile,
199:         }),
200:         12 => Ok(VersionCapabilities {
201:             version,
202:             record_len_width: 2,
203:             scramble_type: ScrambleType::Xor,
204:             details_location: DetailsLocation::HeaderOffset,
205:         }),
206:         13..=14 => Ok(VersionCapabilities {
207:             version,
208:             record_len_width: 2,
209:             scramble_type: ScrambleType::Aes,
210:             details_location: DetailsLocation::HeaderOffset,
211:         }),
212:         unsupported => Err(FlightReaderError::UnsupportedVersion {
213:             version: unsupported,
214:         }),
215:     }
216: }
