//! Adversarial Challenge & Fuzzing Harness for OpenFlightReader Phase 1 Core Library.
//!
//! Stress-tests:
//! 1. `TxtHeader::parse` with fuzzed byte arrays, negative details offsets, boundary header lengths
//!    (99, 100, 101, 102), and corrupted versions (0, 15..255).
//! 2. `DatFrameIterator` with pathological noise streams: streams consisting purely of false 0x55 bytes,
//!    streams with overlapping 0x55 bytes (e.g. 0x55 0x55 0x55), truncated frames with valid headers
//!    but missing payloads/checksums, corrupted checksums.
//! 3. Guarantees: Zero panics, bounded execution / termination (no infinite loops), and clean recovery
//!    of all valid embedded frames.

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::dat::{
    calc_crc16_ccitt, calc_crc32, verify_crc16, verify_crc32, DatChecksumType, DatFrame,
    DatFrameIterator, CRC16_INIT_PRIMARY, DAT_MAGIC,
};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::{
    classify_version, Department, DetailsLocation, ScrambleType, TxtHeader,
};

/// Deterministic Pseudo-Random Number Generator (Xorshift64) for reproducible fuzzing.
struct XorShift64 {
    state: u64,
}

impl XorShift64 {
    fn new(seed: u64) -> Self {
        Self {
            state: if seed == 0 { 0x55AA_55AA_1234_5678 } else { seed },
        }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state = x;
        x
    }

    fn next_u8(&mut self) -> u8 {
        self.next_u64() as u8
    }

    fn fill_bytes(&mut self, buf: &mut [u8]) {
        for b in buf.iter_mut() {
            *b = self.next_u8();
        }
    }
}

/// Helper to create a valid synthetic DJI .txt header buffer.
fn make_raw_header(
    details_offset: i64,
    header_length: i16,
    version: u8,
    dept: u8,
    scrambled: u8,
    padding: Option<u8>,
) -> Vec<u8> {
    let total_len = if padding.is_some() || header_length == 101 {
        101
    } else {
        100
    };
    let mut buf = vec![0u8; total_len];
    LittleEndian::write_i64(&mut buf[0..8], details_offset);
    LittleEndian::write_i16(&mut buf[8..10], header_length);
    buf[10] = version;
    buf[11] = dept;
    buf[12] = scrambled;
    if let Some(pad) = padding {
        buf[100] = pad;
    }
    buf
}

/// Helper to construct a valid CRC16 .DAT frame.
fn make_valid_crc16_frame(seq: u8, payload_id: u16, ticks: u32, payload: &[u8]) -> Vec<u8> {
    let frame_len = 9 + payload.len() + 2;
    assert!(frame_len <= 255);
    let mut frame = vec![0u8; frame_len];
    frame[0] = DAT_MAGIC;
    frame[1] = frame_len as u8;
    frame[2] = seq;
    LittleEndian::write_u16(&mut frame[3..5], payload_id);
    LittleEndian::write_u32(&mut frame[5..9], ticks);
    frame[9..9 + payload.len()].copy_from_slice(payload);
    let crc = calc_crc16_ccitt(&frame[..frame_len - 2], CRC16_INIT_PRIMARY);
    LittleEndian::write_u16(&mut frame[frame_len - 2..], crc);
    frame
}

/// Helper to construct a valid CRC32 .DAT frame.
fn make_valid_crc32_frame(seq: u8, payload_id: u16, ticks: u32, payload: &[u8]) -> Vec<u8> {
    let frame_len = 9 + payload.len() + 4;
    assert!(frame_len <= 255);
    let mut frame = vec![0u8; frame_len];
    frame[0] = DAT_MAGIC;
    frame[1] = frame_len as u8;
    frame[2] = seq;
    LittleEndian::write_u16(&mut frame[3..5], payload_id);
    LittleEndian::write_u32(&mut frame[5..9], ticks);
    frame[9..9 + payload.len()].copy_from_slice(payload);
    let crc = calc_crc32(&frame[..frame_len - 4]);
    LittleEndian::write_u32(&mut frame[frame_len - 4..], crc);
    frame
}

// =============================================================================
// CHALLENGE SUITE 1: TxtHeader::parse ADVERSARIAL STRESS & FUZZING
// =============================================================================

#[test]
fn challenge_txt_header_fuzzed_byte_arrays_no_panics() {
    let mut rng = XorShift64::new(0x1337_CAFE_DEAD_BEEF);
    const NUM_ITERATIONS: usize = 10_000;

    for i in 0..NUM_ITERATIONS {
        // Vary lengths from 0 up to 350 bytes
        let len = (i % 351) as usize;
        let mut fuzzed = vec![0u8; len];
        rng.fill_bytes(&mut fuzzed);

        // Fuzz parser: must return Result, NEVER panic or abort
        let res = TxtHeader::parse(&fuzzed);
        if len < 100 {
            assert_eq!(
                res.unwrap_err(),
                FlightReaderError::UnexpectedEof,
                "Buffer with len < 100 must fail with UnexpectedEof"
            );
        } else if let Ok(header) = res {
            // Invariants on successfully parsed headers
            assert!(header.details_offset >= 0);
            assert!(header.header_length == 100 || header.header_length == 101);
            assert!((1..=14).contains(&header.version));
            if header.header_length == 101 {
                assert!(header.padding.is_some());
            } else {
                assert!(header.padding.is_none());
            }
        }
    }
}

#[test]
fn challenge_txt_header_negative_details_offset_spectrum() {
    // Adversarial offsets including signed edge cases
    let negative_offsets: &[i64] = &[
        -1,
        -2,
        -10,
        -100,
        -1000,
        -65536,
        -2_147_483_648,
        -4_294_967_296,
        i64::MIN + 1,
        i64::MIN,
    ];

    for &bad_offset in negative_offsets {
        for ver in 1..=14 {
            for &hlen in &[100i16, 101i16] {
                let pad = if hlen == 101 { Some(0x00) } else { None };
                let bytes = make_raw_header(bad_offset, hlen, ver, 2, 0, pad);
                let err = TxtHeader::parse(&bytes).unwrap_err();
                assert_eq!(
                    err,
                    FlightReaderError::CorruptedHeader,
                    "Negative details offset {} (ver={}, hlen={}) must yield CorruptedHeader",
                    bad_offset,
                    ver,
                    hlen
                );
            }
        }
    }
}

#[test]
fn challenge_txt_header_boundary_lengths_99_100_101_102() {
    // 1. Boundary length 99: Must reject with InvalidHeaderLength { length: 99 }
    let h99 = make_raw_header(10000, 99, 1, 2, 0, None);
    assert_eq!(
        TxtHeader::parse(&h99).unwrap_err(),
        FlightReaderError::InvalidHeaderLength { length: 99 }
    );

    // 2. Boundary length 100:
    // With 100 bytes buffer -> Valid
    let h100 = make_raw_header(10000, 100, 1, 2, 0, None);
    assert_eq!(h100.len(), 100);
    let parsed100 = TxtHeader::parse(&h100).expect("Valid 100B header");
    assert_eq!(parsed100.header_length, 100);
    assert_eq!(parsed100.padding, None);

    // With 99 bytes buffer -> UnexpectedEof
    assert_eq!(
        TxtHeader::parse(&h100[..99]).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 3. Boundary length 101:
    // With 101 bytes buffer -> Valid
    let h101 = make_raw_header(10000, 101, 13, 3, 1, Some(0x5A));
    assert_eq!(h101.len(), 101);
    let parsed101 = TxtHeader::parse(&h101).expect("Valid 101B header");
    assert_eq!(parsed101.header_length, 101);
    assert_eq!(parsed101.padding, Some(0x5A));

    // With 100 bytes buffer (missing the 101st byte) -> UnexpectedEof
    assert_eq!(
        TxtHeader::parse(&h101[..100]).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 4. Boundary length 102: Must reject with InvalidHeaderLength { length: 102 }
    let mut h102 = make_raw_header(10000, 102, 1, 2, 0, None);
    h102.push(0x00);
    h102.push(0x00);
    assert_eq!(
        TxtHeader::parse(&h102).unwrap_err(),
        FlightReaderError::InvalidHeaderLength { length: 102 }
    );
}

#[test]
fn challenge_txt_header_corrupted_versions_exhaustive_sweep() {
    let mut valid_count = 0;
    let mut invalid_count = 0;

    for v in 0..=255u8 {
        let bytes = make_raw_header(10000, 100, v, 2, 0, None);
        match TxtHeader::parse(&bytes) {
            Ok(header) => {
                valid_count += 1;
                assert!(
                    (1..=14).contains(&v),
                    "Version {} was accepted but is not in 1..=14",
                    v
                );
                assert_eq!(header.version, v);
            }
            Err(FlightReaderError::UnsupportedVersion { version }) => {
                invalid_count += 1;
                assert!(
                    v == 0 || v >= 15,
                    "Version {} was rejected as unsupported",
                    v
                );
                assert_eq!(version, v);
            }
            Err(other) => panic!("Unexpected error variant for version {}: {:?}", v, other),
        }
    }

    // Exactly 14 supported versions (1 through 14)
    assert_eq!(valid_count, 14, "Exactly versions 1..=14 must be valid");
    // Exactly 242 unsupported versions (0 and 15..=255)
    assert_eq!(
        invalid_count, 242,
        "Exactly 242 versions must be rejected as UnsupportedVersion"
    );
}

#[test]
fn challenge_txt_header_extreme_int16_lengths() {
    let pathological_lengths: &[i16] = &[
        i16::MIN,
        -32767,
        -1000,
        -101,
        -100,
        -1,
        0,
        1,
        50,
        98,
        103,
        256,
        1024,
        32766,
        i16::MAX,
    ];

    for &len in pathological_lengths {
        let bytes = make_raw_header(50000, len, 8, 3, 1, None);
        let err = TxtHeader::parse(&bytes).unwrap_err();
        assert_eq!(
            err,
            FlightReaderError::InvalidHeaderLength { length: len },
            "Pathological header length {} must be rejected with InvalidHeaderLength",
            len
        );
    }
}

// =============================================================================
// CHALLENGE SUITE 2: DatFrameIterator PATHOLOGICAL NOISE & SYNC STRESS
// =============================================================================

#[test]
fn challenge_dat_iterator_pure_0x55_streams_never_hang_or_panic() {
    // Streams of repeating 0x55 bytes across various lengths
    let stream_sizes = [
        0usize, 1, 2, 3, 4, 8, 9, 10, 11, 12, 13, 20, 27, 35, 50, 85, 100, 255, 500, 1000, 5000,
    ];

    for &size in &stream_sizes {
        let pure_0x55 = vec![DAT_MAGIC; size];
        let mut iter = DatFrameIterator::new(&pure_0x55);
        let mut yielded_frames = 0;
        let mut step_count = 0;

        while let Some(res) = iter.next() {
            if let Ok(frame) = res {
                yielded_frames += 1;
                // If pure 0x55 miraculously matched a checksum, verify frame consistency
                assert_eq!(frame.magic, DAT_MAGIC);
                assert!(frame.length >= 11);
            }
            step_count += 1;
            // Strict loop guard: step count can never exceed stream size
            assert!(
                step_count <= size,
                "DatFrameIterator stepped {} times on stream size {}",
                step_count,
                size
            );
        }

        // Exhausted iterator must reach end of buffer
        assert_eq!(
            iter.cursor(),
            size,
            "Cursor must reach buffer end for size {}",
            size
        );
        assert!(iter.remaining().is_empty());
    }
}

#[test]
fn challenge_dat_iterator_overlapping_0x55_sync_recovery() {
    // Construct valid test frames
    let valid_f1 = make_valid_crc16_frame(1, 0x0001, 100_000, &[0x11, 0x22, 0x33, 0x44]);
    let valid_f2 = make_valid_crc32_frame(2, 0x0012, 200_000, &[0xAA, 0xBB, 0xCC, 0xDD]);
    let valid_f3 = make_valid_crc16_frame(3, 0x000A, 300_000, &[0x55, 0x55]); // Payload contains 0x55

    // Build stream with pathological overlapping 0x55 patterns:
    // [0x55, 0x55, 0x55, 0x55] + valid_f1 + [0x55, 0x55, 0x55] + valid_f2 + [0x55, 0x55, 0x55, 0x55, 0x55] + valid_f3 + [0x55, 0x55]
    let mut stream = Vec::new();
    stream.extend_from_slice(&[0x55, 0x55, 0x55, 0x55]);
    stream.extend_from_slice(&valid_f1);
    stream.extend_from_slice(&[0x55, 0x55, 0x55]);
    stream.extend_from_slice(&valid_f2);
    stream.extend_from_slice(&[0x55, 0x55, 0x55, 0x55, 0x55]);
    stream.extend_from_slice(&valid_f3);
    stream.extend_from_slice(&[0x55, 0x55]);

    let iter = DatFrameIterator::new(&stream);
    let frames: Vec<DatFrame> = iter
        .collect::<Result<Vec<_>, _>>()
        .expect("Overlapping 0x55 stream must parse cleanly without returning error");

    assert_eq!(
        frames.len(),
        3,
        "All 3 valid frames must be recovered despite overlapping 0x55 noise"
    );

    // Frame 1 check
    assert_eq!(frames[0].sequence, 1);
    assert_eq!(frames[0].payload_id, 0x0001);
    assert_eq!(frames[0].payload, &[0x11, 0x22, 0x33, 0x44]);
    assert_eq!(frames[0].checksum_type, DatChecksumType::Crc16);

    // Frame 2 check
    assert_eq!(frames[1].sequence, 2);
    assert_eq!(frames[1].payload_id, 0x0012);
    assert_eq!(frames[1].payload, &[0xAA, 0xBB, 0xCC, 0xDD]);
    assert_eq!(frames[1].checksum_type, DatChecksumType::Crc32);

    // Frame 3 check (contains 0x55 in payload)
    assert_eq!(frames[2].sequence, 3);
    assert_eq!(frames[2].payload_id, 0x000A);
    assert_eq!(frames[2].payload, &[0x55, 0x55]);
    assert_eq!(frames[2].checksum_type, DatChecksumType::Crc16);
}

#[test]
fn challenge_dat_iterator_truncated_frames_clean_recovery() {
    let valid_frame = make_valid_crc16_frame(10, 0x0005, 500_000, &[1, 2, 3, 4, 5, 6]);

    // Construct a candidate with valid 9-byte header declaring length 30, but buffer truncated
    let mut truncated_candidate = vec![0u8; 9];
    truncated_candidate[0] = DAT_MAGIC;
    truncated_candidate[1] = 30; // Declares 30 bytes
    truncated_candidate[2] = 99; // Seq
    LittleEndian::write_u16(&mut truncated_candidate[3..5], 0x0002);
    LittleEndian::write_u32(&mut truncated_candidate[5..9], 1234);
    // Add only 5 bytes of body (total 14 bytes instead of declared 30)
    truncated_candidate.extend_from_slice(&[0x10, 0x20, 0x30, 0x40, 0x50]);

    // Stream: truncated_candidate + noise + valid_frame + trailing partial
    let mut stream = Vec::new();
    stream.extend_from_slice(&truncated_candidate);
    stream.extend_from_slice(&[0xAA, 0xBB, 0xCC]);
    stream.extend_from_slice(&valid_frame);
    stream.extend_from_slice(&[0x55, 0x20]); // Incomplete candidate header at stream EOF

    let mut iter = DatFrameIterator::new(&stream);
    let first = iter.next().expect("Must recover the valid frame");
    let frame = first.expect("Must be Ok");
    assert_eq!(frame.sequence, 10);
    assert_eq!(frame.payload_id, 0x0005);
    assert_eq!(frame.payload, &[1, 2, 3, 4, 5, 6]);

    // Stream should cleanly terminate
    assert!(iter.next().is_none());
    assert_eq!(iter.cursor(), stream.len());
}

#[test]
fn challenge_dat_corrupted_checksums_stress() {
    let valid_frame = make_valid_crc16_frame(5, 0x0001, 100_000, &[10, 20, 30, 40]);
    let len = valid_frame.len();

    // Single bit flip across EVERY bit in the frame
    for byte_idx in 0..len {
        for bit in 0..8 {
            let mut corrupted = valid_frame.clone();
            corrupted[byte_idx] ^= 1 << bit;

            // Direct parse must fail
            let res = DatFrame::parse(&corrupted);
            assert!(
                res.is_err(),
                "Bit flip at byte {}, bit {} must be rejected by DatFrame::parse",
                byte_idx,
                bit
            );

            // DatFrameIterator must skip the corrupted frame and not yield false data
            let mut iter = DatFrameIterator::new(&corrupted);
            assert!(
                iter.next().is_none(),
                "Iterator must yield None on corrupted single-frame stream (byte {}, bit {})",
                byte_idx,
                bit
            );
        }
    }
}

#[test]
fn challenge_dat_pathological_composite_stress_stream_50k() {
    let mut rng = XorShift64::new(0x8765_4321_ABCD_EF01);
    const NUM_VALID_FRAMES: usize = 50;

    let mut ground_truth_seqs = Vec::with_capacity(NUM_VALID_FRAMES);
    let mut ground_truth_ids = Vec::with_capacity(NUM_VALID_FRAMES);
    let mut ground_truth_payloads = Vec::with_capacity(NUM_VALID_FRAMES);

    let mut stream = Vec::with_capacity(65_536);

    for i in 0..NUM_VALID_FRAMES {
        // 1. Insert random noise segment (0 to 300 bytes) with high density of 0x55
        let noise_len = (rng.next_u64() % 250) as usize + 10;
        let mut noise = vec![0u8; noise_len];
        rng.fill_bytes(&mut noise);
        // Inject multiple false 0x55 bytes into noise
        for _ in 0..5 {
            let pos = (rng.next_u64() as usize) % noise_len;
            noise[pos] = DAT_MAGIC;
        }
        stream.extend_from_slice(&noise);

        // 2. Generate valid frame
        let seq = (i + 1) as u8;
        let payload_id = ((i * 7 + 1) % 50 + 1) as u16;
        let ticks = (i * 10_000 + 500) as u32;
        let p_len = (rng.next_u64() % 32) as usize; // 0 to 31 bytes payload
        let mut payload = vec![0u8; p_len];
        rng.fill_bytes(&mut payload);

        let frame_bytes = if i % 2 == 0 {
            make_valid_crc16_frame(seq, payload_id, ticks, &payload)
        } else {
            make_valid_crc32_frame(seq, payload_id, ticks, &payload)
        };

        ground_truth_seqs.push(seq);
        ground_truth_ids.push(payload_id);
        ground_truth_payloads.push(payload);

        stream.extend_from_slice(&frame_bytes);
    }

    // Trailing noise
    stream.extend_from_slice(&[0x55, 0x02, 0x55, 0x10, 0xAA, 0xBB, 0x55]);

    // Parse composite stream
    let iter = DatFrameIterator::new(&stream);
    let recovered_frames: Vec<DatFrame> = iter
        .collect::<Result<Vec<_>, _>>()
        .expect("Stream iteration must succeed without error");

    assert_eq!(
        recovered_frames.len(),
        NUM_VALID_FRAMES,
        "Must recover exactly {} valid frames from composite stress stream",
        NUM_VALID_FRAMES
    );

    for (i, frame) in recovered_frames.iter().enumerate() {
        assert_eq!(frame.sequence, ground_truth_seqs[i]);
        assert_eq!(frame.payload_id, ground_truth_ids[i]);
        assert_eq!(frame.payload, ground_truth_payloads[i].as_slice());
        if i % 2 == 0 {
            assert_eq!(frame.checksum_type, DatChecksumType::Crc16);
        } else {
            assert_eq!(frame.checksum_type, DatChecksumType::Crc32);
        }
    }
}

#[test]
fn challenge_dat_iterator_termination_and_cursor_properties() {
    let mut rng = XorShift64::new(0x4242_4242_4242_4242);

    for &size in &[0usize, 1, 2, 7, 11, 13, 27, 64, 128, 512, 2048] {
        let mut data = vec![0u8; size];
        rng.fill_bytes(&mut data);

        let mut iter = DatFrameIterator::new(&data);
        let mut count = 0;
        while let Some(res) = iter.next() {
            let _ = res;
            count += 1;
            // Loop step count cannot exceed size
            assert!(
                count <= size,
                "Iteration count {} exceeded stream size {}",
                count,
                size
            );
        }

        // Iterator must advance to buffer length
        assert_eq!(iter.cursor(), size);
        assert!(iter.remaining().is_empty());
    }
}

